import json
LOW=[2,2,0,0,0,0,0,0,0]
UP=[4,4,4,4,4,4,4,4,4]
DEGS=list(range(4,37)); HS=[1,2,3,4]

def parts():
    out=[]
    def rec(i,prev,a):
        if i==9:
            out.append(tuple(a)); return
        for x in range(min(prev,UP[i]),LOW[i]-1,-1): rec(i+1,x,a+[x])
    rec(0,4,[])
    return out
P=parts()
bydeg={d:sorted([p for p in P if sum(p)==d],reverse=True) for d in DEGS}

def horizontal(mu,la):
    return all(mu[i]>=la[i]>= (mu[i+1] if i<8 else 0) for i in range(9))
def eye(n): return [[1 if i==j else 0 for j in range(n)] for i in range(n)]
def mm(A,B):
    if not A: return []
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def eq(A,B): return A==B
def diag_ok(A):
    m=len(A); n=len(A[0]) if m else 0; z=min(m,n); last=0
    for i in range(m):
      for j in range(n):
        if i!=j and A[i][j]!=0:return False
    for i in range(z):
      if A[i][i]<0:return False
      if A[i][i]!=0:
        if last and A[i][i]%last:return False
        last=A[i][i]
    return True

def smith(M):
    m=len(M); n=len(M[0]) if m else 0
    A=[r[:] for r in M]; U=eye(m); V=eye(n); du=dv=1
    def rs(i,j):
      nonlocal du
      A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]; du=-du
    def cs(i,j):
      nonlocal dv
      for R in (A,V):
       for r in R:R[i],R[j]=R[j],R[i]
      dv=-dv
    def ra(i,j,q):
      # row i += q row j
      for R in (A,U): R[i]=[x+q*y for x,y in zip(R[i],R[j])]
    def ca(i,j,q):
      # column i += q column j
      for R in (A,V):
       for r in R:r[i]+=q*r[j]
    def rn(i):
      nonlocal du
      A[i]=[-x for x in A[i]]; U[i]=[-x for x in U[i]]; du=-du
    k=0
    while k<m and k<n:
      pos=None
      for i in range(k,m):
       for j in range(k,n):
        if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):pos=(i,j)
      if pos is None: break
      rs(k,pos[0]); cs(k,pos[1])
      while True:
       changed=True
       while changed:
        changed=False
        for i in range(k+1,m):
         if A[i][k]:
          q=A[i][k]//A[k][k]; ra(i,k,-q)
          if A[i][k]: rs(i,k)
          changed=True; break
        if changed: continue
        for j in range(k+1,n):
         if A[k][j]:
          q=A[k][j]//A[k][k]; ca(j,k,-q)
          if A[k][j]: cs(j,k)
          changed=True; break
       bad=None
       p=A[k][k]
       for i in range(k+1,m):
        for j in range(k+1,n):
         if A[i][j]%p: bad=(i,j);break
        if bad:break
       if not bad:break
       # introduce a nondivisible entry into pivot row, then Euclidean-reduce it
       ca(k,bad[1],1)
      if A[k][k]<0: rn(k)
      k+=1
    D=A
    return U,V,D,du,dv

records=[]
for d in DEGS:
 cols=bydeg[d]
 rows=[]; labels=[]; zeros=[]
 for t in HS:
  for la in bydeg.get(d-t,[]):
   r=[1 if horizontal(mu,la) else 0 for mu in cols]
   (zeros if not any(r) else rows).append([t,list(la)] if not any(r) else r)
   if any(r): labels.append([t,list(la)])
 M=rows; m=len(M); n=len(cols)
 U,V,D,du,dv=smith(M)
 # direct products; 0-row case is handled explicitly
 UM=mm(U,M) if m else []
 UMV=mm(UM,V) if m else []
 rank=sum(1 for i in range(min(m,n)) if D[i][i]!=0)
 sd=[D[i][i] for i in range(rank)]
 tors=[x for x in sd if x>1]
 records.append({'degree':d,'orderedBasis':[list(x) for x in cols],'rowLabels':labels,'zeroRowLabels':zeros,'M':M,'matrixShape':[m,n],'U':U,'V':V,'D':D,'DShape':[m,n],'smithDiagonal':sd,'rank':rank,'quotientFreeRank':n-rank,'torsionInvariantFactors':tors,'checks':{'UMVEqualsD':eq(UMV,D),'diagonalAndDivisibility':diag_ok(D),'detU':du,'detV':dv,'unimodularU':du in (-1,1),'unimodularV':dv in (-1,1)}})
out={'inputs':{'lower':LOW,'upper':UP,'degrees':DEGS,'hDegrees':HS,'columnOrder':'reverse lexicographic','rowOrder':'h-degree then source reverse lexicographic','pieriRule':'coefficient 1 iff mu_i >= lambda_i >= mu_(i+1), with mu_10=0'},'records':records}
assert all(x['checks']['UMVEqualsD'] and x['checks']['diagonalAndDivisibility'] and x['checks']['unimodularU'] and x['checks']['unimodularV'] for x in records)
print(json.dumps(out,separators=(',',':')))
